from openpyxl.utils import get_column_letter
from pathlib import Path

path = Path('/root/data/workbook.xlsx')
wb = load_workbook(path, data_only=False)
print('WORKBOOK:', path)
print('SHEETS:', wb.sheetnames)

for wsname in ['Task']:
    ws = wb[wsname]
    print('\n' + '='*120)
    print(f'SHEET {wsname}: max_row={ws.max_row}, max_col={ws.max_column}')
    print('Task full contents rows 1-55 cols A-M (value/formula shown as repr):')
    header = ['ROW'] + [get_column_letter(c) for c in range(1,14)]
    print('\t'.join(header))
    for r in range(1,56):
        vals = [str(r)]
        for c in range(1,14):
            v = ws.cell(r,c).value
            vals.append(repr(v) if v is not None else '')
        print('\t'.join(vals))

    print('\nFocused Task series code groups in column D:')
    for label, rows in [('12-17', range(12,18)), ('19-24', range(19,25)), ('26-31', range(26,32)), ('35-40', range(35,41))]:
        print(f'Rows {label}:')
        for r in rows:
            print(f'  D{r}={ws.cell(r,4).value!r}; nearby labels B:E={[ws.cell(r,c).value for c in range(2,6)]!r}')

    print('\nTask row 10 years H-L:')
    for c in range(8,13):
        print(f'  {get_column_letter(c)}10={ws.cell(10,c).value!r}')

    print('\nTask labels/headers rows 11,18,25,34,41,49 cols A-M:')
    for r in [11,18,25,34,41,49]:
        print(f'Row {r}:')
        for c in range(1,14):
            print(f'  {get_column_letter(c)}{r}={ws.cell(r,c).value!r}')

    print('\nExisting content H42:L47 and H50:L50:')
    for r in list(range(42,48))+[50]:
        print(f'Row {r}:')
        for c in range(8,13):
            print(f'  {get_column_letter(c)}{r}={ws.cell(r,c).value!r}')

    print('\nTarget fill colors (H12:L17, H19:L24, H26:L31):')
    for block in [(12,17),(19,24),(26,31)]:
        print(f'Block H{block[0]}:L{block[1]}')
        for r in range(block[0], block[1]+1):
            row=[]
            for c in range(8,13):
                cell=ws.cell(r,c)
                fill=cell.fill
                fg = fill.fgColor.rgb or fill.fgColor.indexed or fill.fgColor.theme or fill.fgColor.type
                row.append(f'{get_column_letter(c)}{r}: type={fill.fill_type}, fg={fg}')
            print('  ' + ' | '.join(row))

ws = wb['Data']
print('\n' + '='*120)
print(f'SHEET Data: max_row={ws.max_row}, max_col={ws.max_column}')
max_col = ws.max_column
print('Data full contents rows 1-40 all populated columns (value/formula shown as repr):')
header = ['ROW'] + [get_column_letter(c) for c in range(1, max_col+1)]
print('\t'.join(header))
for r in range(1,41):
    vals=[str(r)]
    for c in range(1,max_col+1):
        v=ws.cell(r,c).value
        vals.append(repr(v) if v is not None else '')
    print('\t'.join(vals))

print('\nFocused Data rows 21-38 populated cells:')
for r in range(21,39):
    nonempty=[]
    for c in range(1,max_col+1):
        v=ws.cell(r,c).value
        if v is not None:
            nonempty.append(f'{get_column_letter(c)}{r}={v!r}')
    print(f'Row {r}: ' + '; '.join(nonempty))

# simple inference print
print('\nPotential year header cells in Data rows 21-38:')
for r in range(21,39):
    years=[]
    for c in range(1,max_col+1):
        v=ws.cell(r,c).value
        if isinstance(v, int) and 1900 <= v <= 2100:
            years.append(f'{get_column_letter(c)}{r}={v}')
    if years:
        print(f'Row {r}: ' + ', '.join(years))

print('\nPotential series code cells in Data rows 21-38 (strings):')
for r in range(21,39):
    vals=[]
    for c in range(1,max_col+1):
        v=ws.cell(r,c).value
        if isinstance(v, str):
            vals.append(f'{get_column_letter(c)}{r}={v!r}')
    if vals:
        print(f'Row {r}: ' + '; '.join(vals))
